'use strict';

// Arduino firmware template
// Motor driver assumed: DRV8833 (dual H-bridge, no separate enable pins —
// speed is set by PWM-ing the active direction pin directly)
//
// Wiring (can be changed by editing the #define block):
//   AIN1 → D5  (motor 1 / OUT1)
//   AIN2 → D6  (motor 1 / OUT2)
//   BIN1 → D9  (motor 2 / OUT3)
//   BIN2 → D10 (motor 2 / OUT4)
const TEMPLATE = `\
// ============================================================
// Generated by Car Block Coding
// Edit the pin #defines below to match your wiring.
// ============================================================
#include <Arduino.h>

// ── Motor driver pins (DRV8833) ──────────────────────────────
#define AIN1 5   // Motor 1 input 1 (OUT1)
#define AIN2 6   // Motor 1 input 2 (OUT2)
#define BIN1 9   // Motor 2 input 1 (OUT3)
#define BIN2 10  // Motor 2 input 2 (OUT4)
#define LED_PIN 13 // Countdown LED

// ── Turn timing (milliseconds) ───────────────────────────────
// Tune these so 90° and 180° are accurate on your car.
#define TURN_90_MS  514
#define TURN_180_MS 1233

// ── Internal state ───────────────────────────────────────────
static int motorSpeed = 128; // 0–255; applied on the next move* call

// ── Helper functions ─────────────────────────────────────────
void stopMotors() {
  digitalWrite(AIN1, LOW); digitalWrite(AIN2, LOW);
  digitalWrite(BIN1, LOW); digitalWrite(BIN2, LOW);
}

void setSpeed(int level) {
  if      (level == 1) motorSpeed = 51;
  else if (level == 2) motorSpeed = 102;
  else if (level == 3) motorSpeed = 153;
  else if (level == 4) motorSpeed = 204;
  else                 motorSpeed = 255;
}

void moveForward(int ms) {
  analogWrite(AIN1, motorSpeed); digitalWrite(AIN2, LOW);
  analogWrite(BIN2, motorSpeed); digitalWrite(BIN1, LOW);
  delay(ms);
  stopMotors();
}

void moveBackward(int ms) {
  analogWrite(AIN2, motorSpeed); digitalWrite(AIN1, LOW);
  analogWrite(BIN1, motorSpeed); digitalWrite(BIN2, LOW);
  delay(ms);
  stopMotors();
}

void turnLeft(int ms) {
  analogWrite(AIN1, 255); digitalWrite(AIN2, LOW);
  analogWrite(BIN1, 255); digitalWrite(BIN2, LOW);
  delay(ms);
  stopMotors();
}

void turnRight(int ms) {
  analogWrite(AIN2, 255); digitalWrite(AIN1, LOW);
  analogWrite(BIN2, 255); digitalWrite(BIN1, LOW);
  delay(ms);
  stopMotors();
}

// ── Arduino lifecycle ─────────────────────────────────────────
void setup() {
  pinMode(AIN1, OUTPUT); pinMode(AIN2, OUTPUT);
  pinMode(BIN1, OUTPUT); pinMode(BIN2, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  setSpeed(3);
  stopMotors();
  for (int i = 0; i < 5; i++) {
    digitalWrite(LED_PIN, HIGH);
    delay(200);
    digitalWrite(LED_PIN, LOW);
    delay(800);
  }
}

void loop() {
  // ── BEGIN GENERATED CODE ──────────────────────────────────
{{BODY}}
  // ── END GENERATED CODE ────────────────────────────────────

  // Program finished — stop forever
  stopMotors();
  while (true) {}
}
`;

// ── Instruction code generation ───────────────────────────────────────────────

function generateInstruction(node, indent) {
  indent = indent || '  ';
  switch (node.type) {
    case 'move_forward':
      return indent + `moveForward(${Math.round(node.duration * 1000)});`;

    case 'move_backward':
      return indent + `moveBackward(${Math.round(node.duration * 1000)});`;

    case 'turn_left':
      return indent + `turnLeft(TURN_90_MS);`;

    case 'turn_right':
      return indent + `turnRight(TURN_90_MS);`;

    case 'turn_around':
      return indent + `turnLeft(TURN_180_MS);`;

    case 'turn_left_for':
      return indent + `turnLeft(${Math.round(node.duration * 1000)});`;

    case 'turn_right_for':
      return indent + `turnRight(${Math.round(node.duration * 1000)});`;

    case 'wait':
      return indent + `delay(${Math.round(node.duration * 1000)});`;

    case 'set_speed':
      return indent + `setSpeed(${node.level});`;

    case 'light_on':
      return indent + `digitalWrite(LED_PIN, HIGH);`;

    case 'light_off':
      return indent + `digitalWrite(LED_PIN, LOW);`;

    case 'light_flash':
      return indent + `for (int f = 0; f < ${node.times}; f++) { digitalWrite(LED_PIN, HIGH); delay(200); digitalWrite(LED_PIN, LOW); delay(200); }`;

    case 'repeat': {
      const inner = (node.body || []).map((n) => generateInstruction(n, indent + '  ')).join('\n');
      return indent + `for (int rep = 0; rep < ${node.times}; rep++) {\n` + inner + '\n' + indent + '}';
    }

    case 'loop_forever': {
      const inner = (node.body || []).map((n) => generateInstruction(n, indent + '  ')).join('\n');
      return indent + 'while (true) {\n' + inner + '\n' + indent + '}';
    }

    default:
      throw new Error(`Unknown instruction type: "${node.type}"`);
  }
}

// ── Public API ────────────────────────────────────────────────────────────────

function generate(ast) {
  if (!ast || ast.type !== 'program') {
    throw new Error('Invalid AST: expected { type: "program", body: [...] }');
  }
  if (!Array.isArray(ast.body) || ast.body.length === 0) {
    throw new Error('Program has no instructions.');
  }

  const lines = ast.body.map((node) => generateInstruction(node, '  '));
  return TEMPLATE.replace('{{BODY}}', lines.join('\n'));
}

module.exports = { generate };
